using System.Numerics;

namespace CoD.Scripts;

/// <summary>
/// The world square covered by a baked minimap image. Normalized map space is (0,0) at the
/// north-west corner and (1,1) at the south-east: +X is east and world -Z is north.
/// </summary>
public sealed record MinimapLayout(string Scene, string Image, float CentreX, float CentreZ, float WorldSize)
{
    public Vector2 Normalize(Vector3 world) =>
        new((world.X - CentreX) / WorldSize + .5f, (world.Z - CentreZ) / WorldSize + .5f);
}

/// <summary>Layouts are generated by Tools/build_minimaps.py into MinimapLayouts.cs.</summary>
public static partial class MinimapLayouts
{
    public static MinimapLayout? For(string? scene) =>
        Array.Find(Baked, layout => layout.Scene.Equals(scene, StringComparison.OrdinalIgnoreCase));
}

public enum MapContactKind { Self, Friendly, Enemy }

/// <summary>
/// One map marker. Heading is clockwise degrees from north, or NaN when unknown;
/// enemy contacts never carry a heading. Opacity fades revealed enemies out.
/// </summary>
public readonly record struct MapContact(int Id, MapContactKind Kind, Vector3 Position, float Heading, float Opacity = 1)
{
    public bool ShowsHeading => Kind != MapContactKind.Enemy && float.IsFinite(Heading);
    public static MapContact Enemy(int id, Vector3 position, float opacity) => new(id, MapContactKind.Enemy, position, float.NaN, opacity);
}

/// <summary>Presentation-only memory of where enemies were last heard. Never used for gameplay.</summary>
public sealed class MapNoiseMemory(float revealSeconds = 3.0f, float fadeSeconds = 1.0f)
{
    private readonly Dictionary<int, (Vector3 Position, float Time)> _pings = new();
    public float RevealSeconds { get; } = MathF.Max(.1f, revealSeconds);
    public float FadeSeconds { get; } = Math.Clamp(fadeSeconds, 0, MathF.Max(.1f, revealSeconds));

    /// <summary>Records a loud event at the emitter's position at that moment; the marker does not follow movement.</summary>
    public void Report(int id, Vector3 position, float time)
    {
        if (float.IsFinite(position.X) && float.IsFinite(position.Y) && float.IsFinite(position.Z) && float.IsFinite(time))
            _pings[id] = (position, time);
    }

    public void Forget(int id) => _pings.Remove(id);
    public void Clear() => _pings.Clear();

    /// <summary>Returns 0 when the contact is not revealed, otherwise its marker opacity.</summary>
    public float Opacity(int id, float now, out Vector3 position)
    {
        position = default;
        if (!_pings.TryGetValue(id, out var ping)) return 0;
        var age = now - ping.Time;
        if (age < 0 || age >= RevealSeconds)
        {
            if (age >= RevealSeconds) _pings.Remove(id);
            return 0;
        }
        position = ping.Position;
        var fadeStart = RevealSeconds - FadeSeconds;
        return age <= fadeStart || FadeSeconds <= 0 ? 1 : Math.Clamp((RevealSeconds - age) / FadeSeconds, 0, 1);
    }
}

public static class TacticalMap
{
    /// <summary>Unsuppressed gunfire reveals its shooter on the enemy team's map.</summary>
    public static bool RevealsShooter(WeaponDefinition? weapon) => weapon?.Suppressed != true;

    /// <summary>Clockwise degrees from north in [0, 360), or NaN for an invalid/vertical forward vector.</summary>
    public static float Heading(Vector3 forward)
    {
        if (!float.IsFinite(forward.X) || !float.IsFinite(forward.Z) || forward.X * forward.X + forward.Z * forward.Z < 1e-8f)
            return float.NaN;
        var degrees = MathF.Atan2(forward.X, -forward.Z) * 180 / MathF.PI;
        return degrees < 0 ? degrees + 360 : degrees;
    }

    /// <summary>
    /// Top-left of a map layer, in the same units as frameSize, that places the normalized
    /// focus point at the frame's centre.
    /// </summary>
    public static Vector2 FocusOffset(Vector2 focus, float layerSize, float frameSize) =>
        new(frameSize * .5f - focus.X * layerSize, frameSize * .5f - focus.Y * layerSize);

    /// <summary>Layer edge length for a frame that shows visibleWorld metres across.</summary>
    public static float LayerSize(MinimapLayout layout, float frameSize, float visibleWorld) =>
        frameSize * layout.WorldSize / MathF.Max(1, visibleWorld);

    /// <summary>Orders contacts so pooled markers keep the local player, then friendlies, then enemies.</summary>
    public static int Priority(MapContact contact) => (int)contact.Kind;
}
